function terminalGapAlert(states,line){if(!etaModeActive())return null;let groups={};for(const s of states.filter(x=>!x.live&&x.line===line)){let f=s.trip[2][s.trip[2].length-1][0];(groups[f]??=[]).push(s)}let alerts=[];for(const [dest,arr] of Object.entries(groups)){if(arr.length<4)continue;let times=arr.map(s=>s.trip[2][s.trip[2].length-1][1]+(s.delaySec||0)).sort((a,b)=>a-b),gaps=[];for(let i=1;i<times.length;i++){let g=times[i]-times[i-1];if(g>0&&g<1800)gaps.push(g)}if(gaps.length<3)continue;let sorted=[...gaps].sort((a,b)=>a-b),med=sorted[Math.floor(sorted.length/2)],max=Math.max(...gaps),min=Math.min(...gaps);if(max>Math.max(300,med*1.65))alerts.push({kind:'gap',line,dest,seconds:max,median:med});if(min<Math.min(120,med*.55))alerts.push({kind:'bunch',line,dest,seconds:min,median:med})}return alerts.sort((a,b)=>a.kind==='gap'?-1:1)[0]||null}
