function renderMarkers(a){let keep=new Set;for(const s of a){let id=s.live?`LIVE-EAL-${s.train.train_set_id}`:(s.line+'-'+s.trip[0]+'-'+s.trip[2][0][1]);keep.add(id);let el=document.getElementById('m-'+id);if(!el){el=document.createElement('button');el.className='train-marker';el.id='m-'+id;el.innerHTML='<img class="train-model-img" alt=""><span class="speed-bubble"></span>';markers.appendChild(el)}el.style.background=D.lines[s.line].color;el.dataset.line=s.line;let model=window.V11_TRAIN_MODELS?.[s.line],mi=el.querySelector('.train-model-img');if(mi){if(model){mi.src=model.src;mi.alt=model.label||s.line;el.classList.add('train-model-marker')}else{mi.removeAttribute('src');el.classList.remove('train-model-marker')}}el.style.left=(s.pos.x*100)+'%';el.style.top=(s.pos.y*100)+'%';el.style.setProperty('--train-angle',((s.pos.angleDeg||0)+180)+'deg');el.onclick=e=>{e.stopPropagation();s.live?selectLiveTrain(s):selectTrip(s.trip)};el.title=s.live?`EAL ${s.train.td||s.train.train_set_id} · ${Math.round(s.speedKph)} km/h · TELEMETRY · ${s.train.current_station}→${s.train.next_station}`:`${s.line} ${s.trip[0]} · ${Math.round(s.speedKph)} km/h · ${s.phase}${s.etaCorrected?` · ETA ${s.delaySec>=0?'+':''}${Math.round(s.delaySec)}s`:' · WTT FALLBACK'}`;el.querySelector('.speed-bubble').textContent=Math.round(s.speedKph)+' km/h'+(s.live?' · TMS':s.etaCorrected?' · ETA':' · WTT');el.classList.toggle('selected',s.live?selectedLiveId===s.train.train_set_id:selected===s.trip);el.classList.toggle('live-train',!!s.live)}for(const el of [...markers.children]){let id=el.id.slice(2);if(!keep.has(id))el.remove()}}
function renderList(a){let q=$('#search').value.trim().toLowerCase(),items=a.filter(s=>{let label=s.live?`${s.train.train_set_id} ${s.train.td} ${s.train.destination}`:`${s.trip[0]} ${D.lines[s.line].name}`;return !q||label.toLowerCase().includes(q)}).sort((x,y)=>(y.live?1:0)-(x.live?1:0)||(x.live?0:x.b[1])-(y.live?0:y.b[1])).slice(0,180);list.innerHTML=items.length?'':'<div class="empty">No active trains match this view.</div>';for(const s of items){let r=document.createElement('div');r.className='trainRow'+(s.live?' liveRow':'');if(s.live){let tr=s.train;r.innerHTML=`<i style="background:${D.lines.EAL.color}"></i><div><b>EAL ${escapeHtml(tr.td||tr.train_set_id)} <em>LIVE</em></b><span>${escapeHtml(D.stations[s.a[0]]?.name||s.a[0])} → ${escapeHtml(D.stations[s.b[0]]?.name||s.b[0])} · to ${escapeHtml(tr.destination||'—')} · ${s.phase}</span></div><time><b>${Math.round(s.speedKph)} km/h</b><span>${escapeHtml(fmtHktTime(tr.updated_at))}</span></time>`;r.onclick=()=>selectLiveTrain(s)}else{r.innerHTML=`<i style="background:${D.lines[s.line].color}"></i><div><b>${s.line} ${escapeHtml(s.trip[0])} ${s.etaCorrected?'<em>ETA</em>':'<em class="wttTag">WTT</em>'}</b><span>${escapeHtml(D.stations[s.a[0]]?.name||s.a[0])} → ${escapeHtml(D.stations[s.b[0]]?.name||s.b[0])} · ${s.phase}${s.etaCorrected?` · ${s.delaySec>=0?'+':''}${Math.round(s.delaySec)}s`:''}</span></div><time><b>${Math.round(s.speedKph)} km/h</b><span>${fmt((s.b[1]||0)+(s.delaySec||0))}</span></time>`;r.onclick=()=>selectTrip(s.trip)}list.appendChild(r)}}
